import { test, expect } from '@playwright/test';
import * as ui from '../support/ui';

test.setTimeout(240_000);
test.describe("person export", () => {
  test("person export", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg_uma = await ui.userPage(browser, "uma", sheet);
    await ui.setToday(pg_uma, "2026-03-10");
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "10.00"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "20.00"})).toBe(true);
    const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A"}));
    const p_lee_jo = ui.must(await ui.addPerson(pg_uma, {"name": "Lee, Jo", "grade": "B"}));
    const c_ada_0 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "10.00"}));
    expect(await ui.claimAction(pg_uma, c_ada_0, "open")).toBe(true);
    expect(await ui.addAlias(pg_uma, p_ada, "Addie")).toBe(true);
    expect(await ui.hold(pg_uma, p_lee_jo, {"from": "2026-03-01"})).toBe(true);
    expect(await ui.exportPerson(pg_uma, p_ada)).toBe("cell,value\nperson-name,Ada (A)\nperson-grade,A\nperson-claimed,10.00\nperson-due-total,1.00\nperson-statement-count,0\nperson-overdue-total,0.00\nperson-hold,no\nperson-retired,no\nperson-aliases,Addie\nperson-score,0\n");
    expect(await ui.exportPerson(pg_uma, p_lee_jo)).toBe("cell,value\nperson-name,\"Lee, Jo (B)\"\nperson-grade,B\nperson-claimed,0.00\nperson-due-total,0.00\nperson-statement-count,0\nperson-overdue-total,0.00\nperson-hold,yes\nperson-retired,no\nperson-aliases,\nperson-score,0\n");
    const pg_vic = await ui.userPage(browser, "vic", sheet);
    expect(await ui.claimAction(pg_vic, c_ada_0, "settle")).toBe(true);
    await ui.refresh(pg_uma);
    expect(await ui.exportPerson(pg_uma, p_ada)).toBe("cell,value\nperson-name,Ada (A)\nperson-grade,A\nperson-claimed,10.00\nperson-due-total,1.00\nperson-statement-count,0\nperson-overdue-total,0.00\nperson-hold,no\nperson-retired,no\nperson-aliases,Addie\nperson-score,0\n");
  });
