  /**
   * Download everyone on the sheet, retired people included, in list order as a CSV file: name, the grade in force
   * today, the retired-from date or nothing, and the due-total as the list shows it.
   */
  protected async exportCsv(): Promise<void> {
    await this.session.settled('people', 'settings');
    const lines = [['name', 'grade', 'retired-from', 'due-total']].concat(
      this.people().map((p) => [p.name, this.gradeOf(p), p.retiredFrom ?? '', this.dueTotalOf(p)]),
    );
    this.download(lines, `people-${this.session.sheet() ?? 'sheet'}.csv`);
  }

  /**
   * Download every claim on the sheet as a CSV file, retired people included, people in list order and each person's
   * claims oldest first: the person's name, then the claim's number, date, amount, due, status and period as the list
   * shows them.
   */
  protected async exportClaims(): Promise<void> {
    await this.session.settled('people', 'settings');
    const lines = [['person', 'number', 'date', 'amount', 'due', 'status', 'period']].concat(
      this.people().flatMap((p) =>
        [...this.claimsOf(p.id)]
          .reverse()
          .map((c) => [
            p.name,
            c.number ?? '',
            c.date,
            c.amount,
            claimDue(c, this.rates(), p.grades, this.session),
            c.status,
            periodOn(this.periods(), c.dueBy)?.name ?? '',
          ]),
      ),
    );
    this.download(lines, `claims-${this.session.sheet() ?? 'sheet'}.csv`);
  }

  /**
   * Download each person's period figures as a CSV file, people in list order and periods in the order they were
   * added: the person's name, the period's name, and their due-total and carried figure for it as the row shows them.
   */
  protected async exportPeriods(): Promise<void> {
    await this.session.settled('people', 'settings');
    const periods = [...this.periods()].sort((a, b) => a.id - b.id);
    const lines = [['person', 'period', 'figure', 'carried']].concat(
      this.people().flatMap((p) =>
        periods.map((per) => [p.name, per.name, this.periodDueTotalOf(p, per), this.carriedOf(p, per)]),
      ),
    );
    this.download(lines, `periods-${this.session.sheet() ?? 'sheet'}.csv`);
  }

  /**
   * Download the person's statement as a CSV file: each claim of theirs bound by their last statement, oldest first,
   * with its number, date, amount, bound figure and status as the list shows them.
   */
  protected async exportStatement(p: Person): Promise<void> {
    await this.session.settled('people', 'settings');
    const person = this.people().find((q) => q.id === p.id) ?? p;
    const lines = [['number', 'date', 'amount', 'figure', 'status']].concat(
      [...this.claimsOf(person.id)]
        .reverse()
        .filter((c) => c.stated)
        .map((c) => [
          c.number ?? '',
          c.date,
          c.amount,
          claimDue(c, this.rates(), person.grades, this.session),
          c.status,
        ]),
    );
    this.download(lines, `statement-${this.session.sheet() ?? 'sheet'}-${person.id}.csv`);
  }

  /** Save the lines of fields as a CSV file of the name, each line ended by a line feed. */
  private download(lines: string[][], name: string): void {
    const text = lines.map((fields) => fields.map(csvField).join(',') + '\n').join('');
    const url = URL.createObjectURL(new Blob([text], { type: 'text/csv;charset=utf-8' }));
    const link = document.createElement('a');
    link.href = url;
    link.download = name;
    link.click();
    setTimeout(() => URL.revokeObjectURL(url));
  }

  /** Re-read the sheet and show the stored values of the person in the open editor. */
  private async reloadEditor(sheet: string, id: number): Promise<void> {
    await this.read(sheet);
    const person = this.people().find((p) => p.id === id);
    if (person && this.editing() === id && this.session.sheet() === sheet) {
      this.editingVersion = person.version;
      this.name.set(person.name);
      this.grade.set(this.gradeOf(person));
      this.terms.set(person.undatedTerms === null ? '' : String(person.undatedTerms));
    this.contact.set(person.contact ?? '');
      this.personTags.set(this.personTagsOf(person).join(', '));
    }
  }

  private async read(sheet: string): Promise<void> {
    const read = ++this.reads;
    const load = this.session.loaded();
    const url = `/api/sheets/${encodeURIComponent(sheet)}`;
    const [list, claims, rates, periods, tags, descendants] = await Promise.all([
      firstValueFrom(this.http.get<Person[]>(`${url}/people`, this.session.headers())),
      firstValueFrom(this.http.get<Claim[]>(`${url}/claims`, this.session.headers())),
      firstValueFrom(this.http.get<Rate[]>(`${url}/rates`, this.session.headers())),
      firstValueFrom(this.http.get<Period[]>(`${url}/periods`, this.session.headers())),
      firstValueFrom(this.http.get<string[]>(`${url}/claims/tags`, this.session.headers())),
      firstValueFrom(this.http.get<DescendantFigures>(`${url}/descendants/figures`, this.session.headers())),
    ]).catch(() => [null, null, null, null, null, null]);
    // A later read wins over a slower earlier one.
    if (list && claims && rates && periods && tags && descendants && read === this.reads && this.session.sheet() === sheet) {
      this.people.set(list);
      this.claims.set(claims);
      this.rates.set(rates);
      this.periods.set(periods);
      this.tags.set(tags);
      this.descendantFigures.set(descendants);
      this.session.shown('people', load);
    }
  }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, Pipe, PipeTransform, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session } from './session';

/** The locales a user may choose. */
export const LOCALES = ['en', 'de'] as const;
export type Locale = (typeof LOCALES)[number];

interface LocaleView {
  locale: Locale;
}

/** A figure as the app computes and stores it: a number with two decimals. */
const FIGURE = /^(-?)(\d+)\.(\d{2})$/;

// The signed-in user's locale, saved per user: it decides how the screen shows them figures. Entries are typed, and
// exports and audit records written, the same under every locale.
@Injectable({ providedIn: 'root' })
export class UserLocale {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  /** The signed-in user's locale: en until it is read. */
  readonly locale = signal<Locale>('en');

  /** Re-read the signed-in user's locale. */
  async read(): Promise<void> {
    const user = this.session.user();
    const view = await firstValueFrom(this.http.get<LocaleView>('/api/me/locale', this.session.headers()));
    if (this.session.user() === user) this.locale.set(view.locale);
  }

  /** Save the signed-in user's locale. */
  async choose(locale: Locale): Promise<void> {
    const user = this.session.user();
    const view = await firstValueFrom(this.http.put<LocaleView>('/api/me/locale', { locale }, this.session.headers()));
    if (this.session.user() === user) this.locale.set(view.locale);
  }

  /** The text as shown under the user's locale: under de a figure reads 1.234,56; anything else is left as it is. */
  show(text: unknown): unknown {
    if (this.locale() !== 'de' || typeof text !== 'string') return text;
    const figure = FIGURE.exec(text);
    if (!figure) return text;
    const [, sign, whole, cents] = figure;
    return `${sign}${whole.replace(/\B(?=(\d{3})+$)/g, '.')},${cents}`;
  }
}

